   161→    for (let i = 0; i < numCabins; i++) {
   162→        const angle = (i / numCabins) * Math.PI * 2;
   163→
   164→        // Create a group for each cabin. This group's origin is the pivot point on the rim.
   165→        const cabinGroup = new THREE.Group();
