   175→        const armStartPoint = new THREE.Vector3(0, 0, 0); // Relative to cabinGroup pivot
   176→        const armEndPoint = new THREE.Vector3(0, -cabinSuspensionArmLength, 0);
   177→        const suspensionArmMesh = createCylinderBeam(armStartPoint, armEndPoint, 0.1, `cabin_arm_${i}`);
