   188→        // Create a decorative roof for the cabin
   189→        const cabinRoofGeometry = new THREE.ConeGeometry(cabinRadius * 1.1, 0.5, 8);
   190→        const cabinRoofMesh = new THREE.Mesh(cabinRoofGeometry);
   191→        cabinRoofMesh.name = `cabin_roof_${i}`;
   192→        cabinRoofMesh.position.y = -cabinSuspensionArmLength - (cabinHeight) + cabinHeight;
   193→        cabinGroup.add(cabinRoofMesh);
   194→
   195→        // Create a floor for the cabin
   196→        const cabinFloorGeometry = new THREE.CylinderGeometry(cabinRadius, cabinRadius, 0.1, 8);
   197→        const cabinFloorMesh = new THREE.Mesh(cabinFloorGeometry);
   198→        cabinFloorMesh.name = `cabin_floor_${i}`;
   199→        cabinFloorMesh.position.y = -cabinSuspensionArmLength - cabinHeight;
   200→        cabinGroup.add(cabinFloorMesh);
   201→    }
